// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [223021509, 2988120517, 3903449541, 795017669, 3596194245, 3221690821, 2079943109, 1218169285, 3393468869, 3361509829, 897589701, 2402736581, 4121309637, 1563453893, 1670144453, 2836156869];
const blocks = ["NFKD U+0A0000-U+0A0FFF", "NFKD U+0A1000-U+0A1FFF", "NFKD U+0A2000-U+0A2FFF", "NFKD U+0A3000-U+0A3FFF", "NFKD U+0A4000-U+0A4FFF", "NFKD U+0A5000-U+0A5FFF", "NFKD U+0A6000-U+0A6FFF", "NFKD U+0A7000-U+0A7FFF", "NFKD U+0A8000-U+0A8FFF", "NFKD U+0A9000-U+0A9FFF", "NFKD U+0AA000-U+0AAFFF", "NFKD U+0AB000-U+0ABFFF", "NFKD U+0AC000-U+0ACFFF", "NFKD U+0AD000-U+0ADFFF", "NFKD U+0AE000-U+0AEFFF", "NFKD U+0AF000-U+0AFFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 655360 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFKD");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
